// /frontend-react/src/components/MedicationHistoryPage.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar';

// --- MOCK DATA ---
const detail = {
    title: "Medications",
    // BREAKING DOWN the simpleInfo into scannable points
    simplePoints: [
        "Blood Pressure Pill (5mg)",
        "Multivitamin",
        "Both are taken every morning.",
        "No recent changes to prescriptions."
    ],
    pdfLink: "Link_to_detailed_Medication_History_Report.pdf",
    color: { bg: '#E8F0FE', border: '#1A73E8', emoji: '💊' },
};

const PHONE_MAX_WIDTH = '450px';

function MedicationHistoryPage({ isEasyMode, goToPage, onMenuClick }) {
    const { t } = useTranslation();
    
    // --- Styles ---
    
    // Style for the main container holding the bullet points
    const summaryContainerStyle = {
        margin: '0 auto 40px auto',
        maxWidth: '350px',
        textAlign: 'left',
        padding: '0 15px', // Padding for content alignment
    };

    const listStyle = {
        listStyle: 'disc', // Standard bullet points
        paddingLeft: isEasyMode ? '40px' : '30px',
        margin: '20px 0 30px 0',
    };

    // Style for individual list items (large font)
    const listItemStyle = {
        fontSize: isEasyMode ? '30px' : '20px',
        lineHeight: '1.6',
        fontWeight: 'bold',
        color: '#333',
        marginBottom: '15px',
    };

    const preciseButtonStyle = {
        padding: '15px 30px', 
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px',
        border: 'none',
        cursor: 'pointer',
        marginTop: '10px', 
        backgroundColor: '#DC3545', 
        color: 'white',
        boxShadow: '0 4px 10px rgba(0,0,0,0.3)',
        transition: 'background-color 0.2s',
    };

    const handleViewPrecise = () => {
        alert(`Opening PRECISE REPORT for ${detail.title} \nLink: ${detail.pdfLink}`);
        console.log(`Precise Report Link: ${detail.pdfLink}`);
    };

    return (
        <div 
            style={{ padding: '0 20px 20px 20px', maxWidth: PHONE_MAX_WIDTH, margin: '0 auto' }}
        >
            <HeaderBar
                title={detail.title}
                onBackClick={() => goToPage('medical-history')} 
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '60px 0 10px 0', color: detail.color.border, textAlign: 'center' }}>
                {t('history_details.simple_summary')}
            </h2>

            <div style={{textAlign: 'center', marginBottom: '20px'}}>
                <span style={{ fontSize: isEasyMode ? '90px' : '60px', display: 'block' }}>
                    {detail.color.emoji}
                </span>
            </div>

            {/* --- Easy Mode Summary Content (Bulleted List) --- */}
            <div style={summaryContainerStyle}>
                <ul style={listStyle}>
                    {detail.simplePoints.map((point, index) => (
                        <li key={index} style={listItemStyle}>
                            {point}
                        </li>
                    ))}
                </ul>
            </div>
            
            {/* --- Call to Action for Caregivers/Others --- */}
            <h3 style={{ fontSize: isEasyMode ? '30px' : '20px', margin: '40px 0 10px 0', textAlign: 'center', color: '#666' }}>
                {t('history_details.precise_access_prompt')}
            </h3>

            <div style={{ textAlign: 'center' }}>
                <button onClick={handleViewPrecise} style={preciseButtonStyle}>
                    {t('history_details.view_precise_report')}
                </button>
                <p style={{ fontSize: isEasyMode ? '18px' : '12px', marginTop: '15px', color: '#999' }}>
                    {t('history_details.precise_report_note')}
                </p>
            </div>
        </div>
    );
}

export default MedicationHistoryPage;
